import java.util.*;

class Solution {
    public int maxSubarraySumCircular(int[] ring) {
        int total = 0;
        int curMax = 0, maxS = Integer.MIN_VALUE;
        int curMin = 0, minS = Integer.MAX_VALUE;
        for (int x : ring) {
            total += x;
            curMax = Math.max(x, curMax + x); maxS = Math.max(maxS, curMax);
            curMin = Math.min(x, curMin + x); minS = Math.min(minS, curMin);
        }
        if (maxS < 0) return maxS;            // all negative: wrapping would mean an empty stretch
        return Math.max(maxS, total - minS);  // normal stretch vs. ring minus the worst middle part
    }
}

