class Solution:
    def maxSubarraySumCircular(self, ring: List[int]) -> int:
        best = worst = cmax = cmin = ring[0]; total = ring[0]
        for x in ring[1:]:
            cmax = max(x, cmax + x); best = max(best, cmax)
            cmin = min(x, cmin + x); worst = min(worst, cmin)
            total += x
        return best if best < 0 else max(best, total - worst)

